import numpy as np, ot, random, itertools

def greedy_assignment(M):
    n=M.shape[0]
    assigned_cols=set()
    rows_order=np.argsort(M.min(axis=1))
    P=[None]*n
    for r in rows_order:
        c=np.argmin(M[r])
        if c not in assigned_cols:
            P[r]=c; assigned_cols.add(c)
        else:
            # pick next min not used
            sorted_idx=np.argsort(M[r])
            for c2 in sorted_idx:
                if c2 not in assigned_cols:
                    P[r]=c2; assigned_cols.add(c2); break
    # For unassigned (shouldn't) pick leftover
    left=[c for c in range(n) if c not in assigned_cols]
    for r in range(n):
        if P[r] is None:
            P[r]=left.pop()
    return P

def test(n,seed):
    np.random.seed(seed)
    a=ot.utils.unif(n)
    b=ot.utils.unif(n)
    X=np.random.rand(n,2)
    Y=np.random.rand(n,2)
    M=ot.dist(X,Y)
    P=greedy_assignment(M)
    G=np.zeros_like(M)
    G[np.arange(n),P]=1/n
    G_opt=ot.lp.emd(a,b,M,check_marginals=False)
    return np.allclose(G,G_opt)

for n in [50,100,200]:
    ok=True
    for seed in range(100):
        if not test(n,seed):
            ok=False; print('fail',n,seed); break
    print(n, ok)
