from scipy.spatial import cKDTree
from scipy.optimize import linear_sum_assignment

def simple_match(src, tgt):
    idxs_src = np.argsort(src[:,0])
    idxs_tgt = np.argsort(tgt[:,0])
    match = dict(zip(idxs_src, idxs_tgt))
    row = []; col = []
    for r,c in match.items():
        row.append(r); col.append(c)
    return np.array(row), np.array(col)

def test(n, seed):
    np.random.seed(seed)
    src = np.random.rand(n,2); tgt = np.random.rand(n,2)
    M = ot.dist(src, tgt)
    row1, col1 = linear_sum_assignment(M)
    row2, col2 = simple_match(src, tgt)
    return set(zip(row1,col1)) == set(zip(row2,col2))

for n in [50,100]:
    print(n, sum(test(n,s) for s in range(100)))
